import pulp

# Create the optimization model
model = pulp.LpProblem("Cargo_Shipment_Scheduling", pulp.LpMinimize)

# Sets
shipments = [1, 2, 3, 4, 5]
hubs = [1, 2, 3, 4, 5]
hub_names = {1: "H1", 2: "H2", 3: "H3", 4: "H4", 5: "H5"}

# Processing times (hours)
processing_times = {
    1: {5: 8, 4: 7, 1: 4, 2: 8, 3: 8},
    2: {5: 5, 3: 3, 2: 8, 1: 1, 4: 10},
    3: {2: 1, 1: 9, 5: 2, 3: 2, 4: 7},
    4: {1: 5, 3: 5, 5: 4, 4: 3, 2: 10},
    5: {3: 6, 2: 7, 1: 3, 4: 6, 5: 7}
}

# Hub sequences (order of hubs for each shipment)
hub_sequences = {
    1: [5, 4, 1, 2, 3],
    2: [5, 3, 2, 1, 4],
    3: [2, 1, 5, 3, 4],
    4: [1, 3, 5, 4, 2],
    5: [3, 2, 1, 4, 5]
}

# Decision variables
start_time = {}
for i in shipments:
    for h in hubs:
        start_time[(i, h)] = pulp.LpVariable(f"start_s{i}_h{h}", lowBound=0, cat='Continuous')

makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

precedence = {}
for j in hubs:
    for i in shipments:
        for k in shipments:
            if i < k:
                precedence[(i, k, j)] = pulp.LpVariable(f"prec_{i}_{k}_h{j}", cat='Binary')

# Objective: minimize makespan
model += makespan, "R0_minimize_makespan"

# R1: Each shipment must follow its prescribed hub sequence order
for i in shipments:
    seq = hub_sequences[i]
    for idx in range(len(seq) - 1):
        current_hub = seq[idx]
        next_hub = seq[idx + 1]
        model += (
            start_time[(i, next_hub)] >= start_time[(i, current_hub)] + processing_times[i][current_hub],
            f"R1_sequence_s{i}_step{idx}"
        )

# R2: Processing of a shipment at a hub cannot be interrupted once started
# This is implicitly enforced by the continuous processing time variables and the disjunctive constraints

# R3: Each hub can process only one shipment at a time (disjunctive constraints)
M = 1000  # Large constant
for j in hubs:
    for i in shipments:
        for k in shipments:
            if i < k:
                # If i precedes k at hub j
                model += (
                    start_time[(k, j)] >= start_time[(i, j)] + processing_times[i][j] - M * (1 - precedence[(i, k, j)]),
                    f"R3_disjunctive1_h{j}_s{i}_s{k}"
                )
                # If k precedes i at hub j
                model += (
                    start_time[(i, j)] >= start_time[(k, j)] + processing_times[k][j] - M * precedence[(i, k, j)],
                    f"R3_disjunctive2_h{j}_s{i}_s{k}"
                )

# R4: Start times must be non-negative (enforced by variable bounds)

# R5: Makespan must be at least the completion time of each shipment
for i in shipments:
    last_hub = hub_sequences[i][-1]
    model += (
        makespan >= start_time[(i, last_hub)] + processing_times[i][last_hub],
        f"R5_makespan_s{i}"
    )

# R6: For each hub, either shipment i precedes shipment k or shipment k precedes shipment i
# This is already enforced by the binary variable precedence[(i,k,j)] and the disjunctive constraints above
# No additional constraint needed as the binary variable ensures exactly one ordering

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(makespan))

print("\nSchedule:")
for i in shipments:
    print(f"\nShipment {i}:")
    for h in hub_sequences[i]:
        start_val = pulp.value(start_time[(i, h)])
        print(f"  Hub {hub_names[h]}: Start = {start_val:.2f}, Duration = {processing_times[i][h]}, "
              f"Finish = {start_val + processing_times[i][h]:.2f}")

import pulp

# Problem data
route_sequences = [
    [("C", 5), ("B", 5), ("A", 7), ("D", 7)],  # Route 1
    [("D", 4), ("A", 5), ("C", 6), ("B", 1)],  # Route 2
    [("A", 8), ("B", 10), ("C", 2), ("D", 3)], # Route 3
    [("C", 7), ("B", 8), ("A", 1), ("D", 2)]   # Route 4
]

num_routes = 4
num_stages_per_route = 4
hubs = ["A", "B", "C", "D"]

# Create model
model = pulp.LpProblem("Hub_Scheduling", pulp.LpMinimize)

# Decision variables
start_time = {}
for r in range(num_routes):
    for s in range(num_stages_per_route):
        start_time[(r, s)] = pulp.LpVariable(f"start_r{r}_s{s}", lowBound=0, cat='Continuous')

completion_time = pulp.LpVariable("completion_time", lowBound=0, cat='Continuous')

# Binary variables for disjunctive constraints
precedence_binary = {}
for hub in hubs:
    # Find all (route, stage) pairs that use this hub
    stages_at_hub = []
    for r in range(num_routes):
        for s in range(num_stages_per_route):
            if route_sequences[r][s][0] == hub:
                stages_at_hub.append((r, s))

    # Create binary variables for each pair of stages at the same hub
    for i in range(len(stages_at_hub)):
        for j in range(i+1, len(stages_at_hub)):
            r1, s1 = stages_at_hub[i]
            r2, s2 = stages_at_hub[j]
            precedence_binary[(r1, s1, r2, s2)] = pulp.LpVariable(
                f"prec_r{r1}_s{s1}_r{r2}_s{s2}", cat='Binary'
            )

# Objective: minimize makespan
model += completion_time, "R0_minimize_makespan"

# R1: Each handling stage must run continuously once started (non-preemptive)
# This is implicitly handled by the start_time variables and duration parameters
# No explicit constraint needed as we don't have preemption variables

# R2: Each hub can handle only one stage at a time (implemented via R5)

# R3: Stages within a route must follow the given sequence order
for r in range(num_routes):
    for s in range(num_stages_per_route - 1):
        current_hub, current_duration = route_sequences[r][s]
        next_hub, next_duration = route_sequences[r][s+1]
        model += (
            start_time[(r, s)] + current_duration <= start_time[(r, s+1)],
            f"R3_sequence_route{r}_stage{s}"
        )

# R4: Completion time must be greater than or equal to the finish time of every stage
for r in range(num_routes):
    for s in range(num_stages_per_route):
        hub, duration = route_sequences[r][s]
        model += (
            start_time[(r, s)] + duration <= completion_time,
            f"R4_completion_route{r}_stage{s}"
        )

# R5: For any two stages requiring the same hub, one must finish before the other starts
M = 10000  # Large constant (big-M)
for hub in hubs:
    # Find all (route, stage) pairs that use this hub
    stages_at_hub = []
    for r in range(num_routes):
        for s in range(num_stages_per_route):
            if route_sequences[r][s][0] == hub:
                stages_at_hub.append((r, s))

    # Create disjunctive constraints for each pair
    for i in range(len(stages_at_hub)):
        for j in range(i+1, len(stages_at_hub)):
            r1, s1 = stages_at_hub[i]
            r2, s2 = stages_at_hub[j]
            duration1 = route_sequences[r1][s1][1]
            duration2 = route_sequences[r2][s2][1]

            # If precedence_binary[(r1, s1, r2, s2)] = 1, then stage1 finishes before stage2 starts
            # If = 0, then stage2 finishes before stage1 starts

            # Constraint: start_time[(r2, s2)] >= start_time[(r1, s1)] + duration1 - M*(1 - precedence_binary[(r1, s1, r2, s2)])
            model += (
                start_time[(r2, s2)] >= start_time[(r1, s1)] + duration1 - M*(1 - precedence_binary[(r1, s1, r2, s2)]),
                f"R5_disjunctive1_hub{hub}_pair{i}_{j}"
            )

            # Constraint: start_time[(r1, s1)] >= start_time[(r2, s2)] + duration2 - M*precedence_binary[(r1, s1, r2, s2)]
            model += (
                start_time[(r1, s1)] >= start_time[(r2, s2)] + duration2 - M*precedence_binary[(r1, s1, r2, s2)],
                f"R5_disjunctive2_hub{hub}_pair{i}_{j}"
            )

# R6: Start times of all stages must be non-negative
# This is already enforced by lowBound=0 in variable definition, but we add explicit constraints
for r in range(num_routes):
    for s in range(num_stages_per_route):
        model += (
            start_time[(r, s)] >= 0,
            f"R6_nonnegative_route{r}_stage{s}"
        )

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print(f"Optimal makespan: {pulp.value(completion_time):.2f}")

print("\nSchedule:")
for r in range(num_routes):
    print(f"\nRoute {r+1}:")
    for s in range(num_stages_per_route):
        hub, duration = route_sequences[r][s]
        start = pulp.value(start_time[(r, s)])
        print(f"  Stage {s+1}: Hub {hub}, Duration {duration}, Start {start:.2f}, Finish {start+duration:.2f}")

print("\nHub utilization:")
for hub in hubs:
    print(f"\nHub {hub}:")
    # Collect all stages at this hub
    hub_stages = []
    for r in range(num_routes):
        for s in range(num_stages_per_route):
            if route_sequences[r][s][0] == hub:
                hub_stages.append((r, s, pulp.value(start_time[(r, s)]), route_sequences[r][s][1]))

    # Sort by start time
    hub_stages.sort(key=lambda x: x[2])
    for r, s, start, duration in hub_stages:
        print(f"  Route {r+1} Stage {s+1}: {start:.2f} - {start+duration:.2f}")

import pulp

# Create the optimization model
model = pulp.LpProblem("Hospital_Test_Scheduling", pulp.LpMinimize)

# Parameters from the problem
patient_sequences = [
    [("B", 10), ("A", 9), ("D", 5), ("C", 6)],  # Patient 1
    [("D", 9), ("C", 1), ("B", 8), ("A", 2)],   # Patient 2
    [("C", 3), ("D", 4), ("A", 8), ("B", 6)],   # Patient 3
    [("C", 5), ("D", 7), ("B", 7), ("A", 2)]    # Patient 4
]

num_patients = 4
tests_per_patient = 4
equipment_list = ["A", "B", "C", "D"]

# Decision variables
start_time = {}
for p in range(num_patients):
    for s in range(tests_per_patient):
        start_time[(p, s)] = pulp.LpVariable(f"start_{p}_{s}", lowBound=0, cat='Continuous')

completion_time = pulp.LpVariable("completion_time", lowBound=0, cat='Continuous')

# Binary variables for sequencing on same equipment
# For each pair of tests (p,s) and (q,t) that use the same equipment, we need a binary variable
# We'll create them on demand when needed
sequence_binary = {}

# First, create a mapping from (patient, test_step) to equipment and duration
equipment_map = {}
duration_map = {}
for p in range(num_patients):
    for s in range(tests_per_patient):
        equipment, duration = patient_sequences[p][s]
        equipment_map[(p, s)] = equipment
        duration_map[(p, s)] = duration

# Create binary variables for all pairs of tests that use the same equipment
for p in range(num_patients):
    for s in range(tests_per_patient):
        for q in range(num_patients):
            for t in range(tests_per_patient):
                if (p, s) >= (q, t):
                    continue  # Avoid duplicates and self-pairs
                if equipment_map[(p, s)] == equipment_map[(q, t)]:
                    sequence_binary[(p, s, q, t)] = pulp.LpVariable(
                        f"seq_{p}_{s}_{q}_{t}", cat='Binary'
                    )

# Objective: minimize completion time
model += completion_time, "R0_minimize_makespan"

# R1: Each test must run continuously once started (no preemption)
# This is implicit in the model structure - we have start times and durations,
# and tests cannot be interrupted because we don't have variables for interruption

# R3: For each patient, tests must be performed in the given sequence order
# R4: Start time of a patient's next test must be at or after the finish time of their previous test
for p in range(num_patients):
    for s in range(tests_per_patient - 1):
        current_duration = duration_map[(p, s)]
        model += (
            start_time[(p, s + 1)] >= start_time[(p, s)] + current_duration,
            f"R3_R4_sequence_patient_{p}_test_{s}"
        )

# R2: Each piece of equipment can process only one test at a time
# R5: For any two tests using the same equipment, one must finish before the other starts (disjunctive constraint)
# We implement this using big-M constraints with binary variables
M = 10000  # Large enough constant (sum of all durations = 10+9+5+6+9+1+8+2+3+4+8+6+5+7+7+2 = 92)

for p in range(num_patients):
    for s in range(tests_per_patient):
        for q in range(num_patients):
            for t in range(tests_per_patient):
                if (p, s) >= (q, t):
                    continue
                if equipment_map[(p, s)] == equipment_map[(q, t)]:
                    # Test (p,s) before (q,t)
                    model += (
                        start_time[(q, t)] >= start_time[(p, s)] + duration_map[(p, s)] - M * (1 - sequence_binary[(p, s, q, t)]),
                        f"R2_R5_disjunctive_1_{p}_{s}_{q}_{t}"
                    )
                    # Test (q,t) before (p,s)
                    model += (
                        start_time[(p, s)] >= start_time[(q, t)] + duration_map[(q, t)] - M * sequence_binary[(p, s, q, t)],
                        f"R2_R5_disjunctive_2_{p}_{s}_{q}_{t}"
                    )

# R6: Completion time is greater than or equal to the finish time of each patient's last test
for p in range(num_patients):
    last_test = tests_per_patient - 1
    last_duration = duration_map[(p, last_test)]
    model += (
        completion_time >= start_time[(p, last_test)] + last_duration,
        f"R6_completion_patient_{p}"
    )

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Optimal completion time:", pulp.value(completion_time))

print("\nSchedule:")
for p in range(num_patients):
    print(f"\nPatient {p+1}:")
    for s in range(tests_per_patient):
        equipment = equipment_map[(p, s)]
        duration = duration_map[(p, s)]
        start = pulp.value(start_time[(p, s)])
        print(f"  Test {s+1}: Equipment {equipment}, Duration {duration}, Start {start:.1f}, Finish {start + duration:.1f}")

print("\nEquipment schedules:")
for eq in equipment_list:
    print(f"\nEquipment {eq}:")
    tests_on_eq = []
    for p in range(num_patients):
        for s in range(tests_per_patient):
            if equipment_map[(p, s)] == eq:
                tests_on_eq.append((p, s, pulp.value(start_time[(p, s)])))

    # Sort by start time
    tests_on_eq.sort(key=lambda x: x[2])
    for p, s, start in tests_on_eq:
        duration = duration_map[(p, s)]
        print(f"  Patient {p+1} Test {s+1}: Start {start:.1f}, Duration {duration}, Finish {start + duration:.1f}")

import pulp

# Create the optimization model
model = pulp.LpProblem("Truck_Dock_Scheduling", pulp.LpMinimize)

# Parameters: truck sequences
truck_sequences = [
    {
        "truck": "T1",
        "sequence": [
            {"dock": "D5", "time": 2},
            {"dock": "D6", "time": 1},
