            {"dock": "D5", "time": 8},
            {"dock": "D2", "time": 5}
        ]
    },
    {
        "truck": "T6",
        "sequence": [
            {"dock": "D2", "time": 8},
            {"dock": "D6", "time": 2},
            {"dock": "D3", "time": 2},
            {"dock": "D1", "time": 8},
            {"dock": "D5", "time": 7},
            {"dock": "D4", "time": 10}
        ]
    }
]

# Decision variables
start_vars = {}
for i, truck_data in enumerate(truck_sequences, start=1):
    truck_id = truck_data["truck"]
    num_steps = len(truck_data["sequence"])
    for k in range(1, num_steps + 1):
        start_vars[(truck_id, k)] = pulp.LpVariable(f"start_{truck_id}_step{k}", lowBound=0, cat='Continuous')

makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += makespan, "minimize_makespan"

# R1 & R2: Each truck must follow its predetermined sequence order with precedence constraints
for i, truck_data in enumerate(truck_sequences, start=1):
    truck_id = truck_data["truck"]
    sequence = truck_data["sequence"]
    num_steps = len(sequence)

    for k in range(1, num_steps):
        # R2: start time of (k+1)-th step >= start time of k-th step + unloading time of k-th step
        model += (
            start_vars[(truck_id, k+1)] >= start_vars[(truck_id, k)] + sequence[k-1]["time"],
            f"R2_{truck_id}_step{k}"
        )

# R3: For each dock, no overlapping intervals
# Collect all tasks by dock
dock_tasks = {}
for i, truck_data in enumerate(truck_sequences, start=1):
    truck_id = truck_data["truck"]
    sequence = truck_data["sequence"]
    for k, step in enumerate(sequence, start=1):
        dock = step["dock"]
        if dock not in dock_tasks:
            dock_tasks[dock] = []
        dock_tasks[dock].append((truck_id, k, step["time"]))

# Create disjunctive constraints for each dock
for dock, tasks in dock_tasks.items():
    for idx1, (truck1, step1, time1) in enumerate(tasks):
        for idx2, (truck2, step2, time2) in enumerate(tasks):
            if idx1 < idx2:  # avoid duplicate and self-pairing
                # Binary variable to decide ordering
                y = pulp.LpVariable(f"order_{dock}_{truck1}{step1}_{truck2}{step2}", cat='Binary')
                M = 10000  # large enough constant

                # Either truck1 finishes before truck2 starts, or truck2 finishes before truck1 starts
                model += (
                    start_vars[(truck2, step2)] >= start_vars[(truck1, step1)] + time1 - M * (1 - y),
                    f"R3_{dock}_{truck1}{step1}_before_{truck2}{step2}_1"
                )
                model += (
                    start_vars[(truck1, step1)] >= start_vars[(truck2, step2)] + time2 - M * y,
                    f"R3_{dock}_{truck1}{step1}_before_{truck2}{step2}_2"
                )

# R4: Makespan must be at least the completion time of the last step for each truck
for i, truck_data in enumerate(truck_sequences, start=1):
    truck_id = truck_data["truck"]
    sequence = truck_data["sequence"]
    last_step = len(sequence)
    last_time = sequence[last_step-1]["time"]
    model += (
        makespan >= start_vars[(truck_id, last_step)] + last_time,
        f"R4_{truck_id}"
    )

# R5: All start times must be non-negative (already enforced by lowBound=0 in variable definition)
# Explicit constraints for clarity
for (truck_id, step), var in start_vars.items():
    model += (var >= 0, f"R5_{truck_id}_step{step}")

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(makespan))
print("\nStart times for each truck:")
for i, truck_data in enumerate(truck_sequences, start=1):
    truck_id = truck_data["truck"]
    sequence = truck_data["sequence"]
    print(f"\n{truck_id}:")
    for k in range(1, len(sequence) + 1):
        print(f"  Step {k} (Dock {sequence[k-1]['dock']}, Time {sequence[k-1]['time']}): "
              f"starts at {pulp.value(start_vars[(truck_id, k)])}")
